                        if area >= 4 and n * 100 >= area * 85:
                            candidates.append((area, n, r0, r1, c0, c1))

        # Prefer the largest high-density patches; discard candidates contained
        # within an already selected patch.
        candidates.sort(key=lambda t: (t[0], t[1]), reverse=True)
        selected = []
        for area, n, r0, r1, c0, c1 in candidates:
            if any(a >= area and rr0 <= r0 and rr1 >= r1 and
                   cc0 <= c0 and cc1 >= c1
                   for a, rr0, rr1, cc0, cc1 in selected):
